package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaThDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("คุ้มครองจากอันตรายทั้งหมด", "ด้วยพระนามของอัลลอฮ์ ซึ่งไม่มีชื่อใดในโลกหรือในชั้นฟ้าทั้งหลายสามารถก่อให้เกิดอันตรายได้ และพระองค์คือผู้ทรงได้ยิน ผู้ทรงรอบรู้", "สามครั้งทุกเช้าและเย็น", "ผู้ใดกล่าวคำนี้สามครั้งเช้าและเย็น ไม่มีอะไรจะทำร้ายเขาได้"),
        "dua_raditu_billahi" to DuaText("ความพอใจต่ออัลลอฮ์ในฐานะพระเจ้า", "ฉันพอใจที่มีอัลลอฮ์เป็นพระเจ้าของฉัน โดยมีอิสลามเป็นศาสนาของฉัน และมูฮัมหมัด ﷺ เป็นศาสดาของฉัน", "สามครั้งเช้าและเย็น", "ถือเป็นสิทธิของอัลลอฮ์ที่จะทรงโปรดเขาในวันกิยามะฮ์"),
        "dua_hasbiyallah" to DuaText("ฮัสบียาลลอฮฺ (อัลลอฮฺทรงพอเพียง)", "อัลลอฮ์นั้นเพียงพอแล้วสำหรับฉัน ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ฉันขอมอบหมายต่อพระองค์ และพระองค์คือพระเจ้าแห่งบัลลังก์อันยิ่งใหญ่", "เจ็ดครั้งเช้าและเย็น", "โองการของอัลกุรอาน; อัลลอฮ์ทรงพอเพียงแล้วกับความกังวลของโลกนี้และปรโลก"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("ซุบฮานัลลอฮิ วา บิฮัมดิฮี", "มหาบริสุทธิ์แด่อัลลอฮ์และการสรรเสริญทั้งหมดเป็นของพระองค์", "วันละร้อยครั้ง", "ใครก็ตามที่พูดมันวันละร้อยครั้ง เขาจะได้รับการอภัยบาปของเขา แม้ว่าความผิดนั้นจะเป็นเหมือนฟองคลื่นในทะเลก็ตาม"),
        "dua_tahleel_100" to DuaText("ลาอิลาฮะ อิลลัลลอฮฺ วะห์ดาฮู", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจนั้นเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง", "คุณธรรมอันยิ่งใหญ่ในการพูดวันละร้อยครั้ง", "รางวัลของการปลดปล่อยทาสสิบคน การเขียนความดีร้อยครั้ง การลบบาปร้อยครั้ง และการปกป้องจากชัยฏอนจนถึงเวลาเย็น"),
        "dua_leaving_mosque" to DuaText("ออกจากมัสยิด", "โอ้อัลลอฮ์ ฉันขอความกรุณาจากพระองค์", "เมื่อก้าวออกจากมัสยิดด้วยเท้าซ้าย", "ขอความโปรดปรานจากอัลลอฮ์และการจัดเตรียมเมื่อออกจากมัสยิด"),
        "dua_after_adhan" to DuaText("หลังอาซาน", "โอ้อัลลอฮ์ พระเจ้าแห่งการเรียกที่สมบูรณ์แบบนี้และการอธิษฐานที่กำลังจะสถาปนา โปรดประทานมุฮัมมัด ﷺ อัล-วาซีละฮ์ และคุณธรรม และโปรดยกเขาขึ้นสู่สถานีสรรเสริญที่คุณได้สัญญาไว้กับเขา", "หลังจากอาซานเสร็จเรียบร้อยแล้ว", "ใครก็ตามที่กล่าวสิ่งนี้จะได้รับการวิงวอนจากศาสดาพยากรณ์ ﷺ ในวันพิพากษา"),
        "dua_after_salah_istighfar" to DuaText("หลังจากฟาด ซาลาห์", "ฉันขอการอภัยโทษจากอัลลอฮ์ (3 ครั้ง) โอ้อัลลอฮ์ พระองค์เป็นสลาม และจากพระองค์คือความสงบสุข สาธุการแด่ท่าน ข้าแต่ผู้ครอบครองพระบารมีและเกียรติยศ", "ทันทีหลังสลาม", "ศาสดาพยากรณ์ ﷺ ท่องสิ่งนี้หลังจากสวดมนต์บังคับทุกครั้ง"),
        "dua_after_salah_help_dhikr" to DuaText("ช่วยฉันจำคุณ", "โอ้อัลลอฮ์ โปรดช่วยให้ฉันรำลึกถึงพระองค์ ขอบคุณและเคารพสักการะพระองค์อย่างดีที่สุด", "หลังจากการละหมาดทุกครั้ง พระศาสดาหมายเลข ﷺ แนะนำให้มุอาซ (RA) กล่าวคำนี้", "คำแนะนำพิเศษของศาสดาพยากรณ์ ﷺ — ความเป็นเลิศและความมั่นคงในการนมัสการ"),
        "dua_sleep_tasbeeh" to DuaText("ตัสบีฮ์อีฟาติมี้ก่อนนอน", "มหาบริสุทธิ์แด่อัลลอฮ์ (33) การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ (33) อัลลอฮ์เป็นผู้ยิ่งใหญ่ที่สุด (34)", "ก่อนนอน ท่านศาสดาหมายเลข ﷺ ได้สอนเรื่องนี้แก่ฟาติมะห์และอาลีหมายเลข (RA)", "ศาสดา ﷺ กล่าวว่าเป็นการดีกว่าสำหรับคุณมากกว่าคนรับใช้"),
        "dua_sleep_qina_adhab" to DuaText("การคุ้มครองจากการลงโทษ", "โอ้อัลลอฮ์ โปรดปกป้องฉันจากการลงโทษของพระองค์ในวันที่พระองค์ฟื้นคืนชีพแก่ปวงบ่าวของพระองค์", "สามครั้งโดยวางมือขวาไว้ใต้แก้ม", "เปลี่ยนการนอนหลับเป็นการเตือนใจถึงความตายและการเตรียมพร้อมสำหรับปรโลก"),
        "dua_bad_dream" to DuaText("หลังจากฝันร้าย", "ฉันขอความคุ้มครองต่ออัลลอฮ์ให้พ้นจากชัยฏอนผู้ถูกสาปแช่ง", "หลังจากฝันร้าย ให้บ้วนน้ำลายไปทางซ้ายเบา ๆ สามครั้ง แล้วเลี้ยวไปอีกด้าน", "ฝันร้ายจะไม่ทำร้ายคุณ อย่าบอกใครเกี่ยวกับเรื่องนี้"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("ยา ฮายู ยา ไกยัม", "ข้าแต่ผู้ดำรงอยู่ตลอดกาล ข้าแต่ผู้ค้ำจุนทุกคน! ด้วยความเมตตาของพระองค์ ข้าพระองค์ขอความช่วยเหลือ", "เมื่อเรื่องใดเรื่องหนึ่งหนักมาก", "เมื่อใดก็ตามที่มีบางสิ่งทำให้ศาสดาพยากรณ์ ﷺ ทุกข์ใจ เขาจะพูดเช่นนี้"),
        "dua_entering_market" to DuaText("เข้าสู่ตลาด", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจของพระองค์เป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ พระองค์ทรงให้ชีวิตและทำให้ตาย และพระองค์ทรงดำรงอยู่ชั่วนิรันดร์และไม่มีวันตาย ทุกสิ่งอยู่ในพระหัตถ์ของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง", "เมื่อเข้าสู่ตลาด.", "สุนัตกล่าวถึงรางวัลอันใหญ่หลวงสำหรับมัน (การทำความดีนับล้าน)"),
        "dua_adam_forgiveness" to DuaText("Dua ของศาสดาอาดัม (AS)", "พระเจ้าของเรา เราได้อธรรมต่อตนเอง และหากพระองค์ไม่ทรงอภัยโทษให้แก่เรา และทรงเมตตาเรา เราก็จะอยู่ในหมู่ผู้ขาดทุนอย่างแน่นอน", "ดุอาการกลับใจของอาดัมและเฮาวา (AS)", "การกลับใจครั้งแรกของมนุษยชาติ — อัลลอฮ์ทรงยอมรับมัน"),
        "dua_abu_bakr" to DuaText("ดุอาอบูบักร (RA)", "โอ้ อัลลอฮ์ ฉันได้อธรรมต่อตัวฉันเองอย่างมหันต์ และไม่มีผู้ใดอภัยบาปได้นอกจากพระองค์ ดังนั้นโปรดให้ฉันอภัยโทษจากพระองค์ด้วยเถิด และโปรดเมตตาฉันด้วย แท้จริงพระองค์เป็นผู้ทรงอภัย ผู้ทรงเมตตาเสมอ", "ศาสดา ﷺ สอนให้อบู บักร อัส-ซิดดิก (RA) พูดในการละหมาด (หลังตะชะหุด)", "ดุอาซุนนะฮฺเพื่อสิ้นสุดการละหมาด"),
        "dua_astaghfirullah_atubu" to DuaText("อิสติฆฟารรายวัน", "ฉันขอการอภัยโทษจากอัลลอฮ์ และฉันขอกลับใจต่อพระองค์", "ศาสดาพยากรณ์ ﷺ แสวงหาการให้อภัยมากกว่าเจ็ดสิบครั้งต่อวัน", "ศาสดา ﷺ กล่าวว่า: ฉันขอการอภัยจากอัลลอฮ์และกลับใจต่อพระองค์มากกว่าเจ็ดสิบครั้งต่อวัน"),
        "dua_laylatul_qadr" to DuaText("Dua สำหรับ Laylat al-Qadr", "โอ้อัลลอฮ์ พระองค์คือผู้ทรงอภัยโทษ และพระองค์ทรงรักที่จะให้อภัย ดังนั้นโปรดยกโทษให้ฉันด้วย", "สอนให้กับอาอิชะฮฺ (RA) สำหรับลัยละตุลก็อดร์", "ดุอาพิเศษสำหรับคืนสุดท้ายของเดือนรอมฎอนและลัยลัตอัลก็อดร์"),
        "dua_family_coolness" to DuaText("ความเยือกเย็นของดวงตา (คู่สมรสและบุตร)", "พระเจ้าของเรา โปรดประทานดวงตาอันเยือกเย็นแก่เราจากคู่ครองของเราและลูกหลานของเรา และโปรดให้เราเป็นผู้นำของบรรดาผู้ยำเกรง", "ดุอาอ์กุรอานสำหรับคู่สมรสและบุตรที่ชอบธรรม", "เพื่อความสงบสุขที่บ้านและลูกหลานที่ชอบธรรม"),
        "dua_righteous_children" to DuaText("สำหรับลูกหลานที่ชอบธรรม", "ข้าแต่พระเจ้าของข้าพระองค์ โปรดประทานลูกหลานอันบริสุทธิ์จากพระองค์แก่ข้าพระองค์ด้วย แท้จริงพระองค์คือผู้ทรงสดับคำวิงวอน", "ดุอาของท่านศาสดาซะการียะห์ (AS)", "ดุอาอัลกุรอานสำหรับผู้ที่กำลังมองหาเด็ก"),
        "dua_ibrahim_prayer_family" to DuaText("ผู้ก่อตั้งการอธิษฐาน", "พระเจ้าของฉัน โปรดให้ฉันเป็นผู้ดำรงการละหมาด และจากลูกหลานของฉันด้วย พระเจ้าของเรา โปรดยอมรับคำวิงวอนของข้าพเจ้าด้วย พระเจ้าของเรา โปรดอภัยโทษให้แก่ฉัน พ่อแม่ของฉัน และบรรดาผู้ศรัทธาในวันที่บัญชีถูกจัดทำขึ้น", "ดุอาของท่านศาสดาอิบราฮิม (AS) สำหรับตัวเขาเองและลูกหลานของเขา", "มักท่องตอนท้ายคำอธิษฐาน"),
        "dua_newlywed" to DuaText("ขอแสดงความยินดีกับคู่บ่าวสาว", "ขออัลลอฮฺทรงอวยพระพรแก่ท่าน ทรงประทานความจำเริญแก่ท่าน และนำท่านทั้งสองมาพบกันด้วยความดี", "เมื่อแสดงความยินดีกับใครสักคนในการแต่งงาน", "ซุนนะฮฺขอแสดงความยินดีกับการแต่งงาน"),
        "dua_before_eating" to DuaText("ก่อนรับประทานอาหาร", "ในนามของอัลลอฮ. (หากลืม:) ด้วยพระนามของอัลลอฮ์ ทั้งในเบื้องต้นและเบื้องปลาย", "ก่อนรับประทานอาหาร ถ้าลืมก็พูดไประหว่างทาง", "การกล่าวบิสมิลลาห์ทำให้ชัยฏนไม่สามารถแบ่งปันอาหารได้"),
        "dua_after_eating" to DuaText("หลังรับประทานอาหาร", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ผู้ทรงเลี้ยงดูฉันสิ่งนี้และจัดเตรียมมันให้ฉันโดยไม่มีกำลังหรืออำนาจใด ๆ ในส่วนของฉัน", "หลังจากทานอาหารเสร็จ", "บาปในอดีตของผู้ที่กล่าวว่าได้รับการอภัยแล้ว"),
        "dua_host" to DuaText("สำหรับเจ้าภาพ", "โอ้อัลลอฮ์ โปรดอวยพรพวกเขาในสิ่งที่พระองค์ได้ประทานแก่พวกเขา ให้อภัยพวกเขา และเมตตาพวกเขาด้วย", "สำหรับเจ้าบ้านหลังจากไปกินข้าวบ้านใครแล้ว", "ขอบคุณเจ้าภาพตามแนวทางซุนนะฮฺ"),
        "dua_breaking_fast" to DuaText("เมื่อละศีลอด", "ความกระหายได้หายไป เส้นโลหิตก็ชุ่มชื้น และรางวัลก็ได้รับการยืนยัน หากอัลลอฮฺทรงประสงค์", "เมื่อถึงเวลาละศีลอด", "ท่านศาสดาหมายเลข ﷺ กล่าวเช่นนี้เมื่อละศีลอด"),
        "dua_new_clothes" to DuaText("สวมเสื้อผ้าใหม่", "โอ้อัลลอฮ์ การสรรเสริญทั้งมวลเป็นของพระองค์ คุณสวมสิ่งนี้ให้ฉัน ฉันขอความคุ้มครองจากพระองค์สำหรับความดีของมัน และความดีของสิ่งที่มันถูกสร้างมา และฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วของมัน และความชั่วของสิ่งที่มันถูกสร้างมา", "เมื่อสวมใส่เสื้อผ้าใหม่ (การตั้งชื่อ เช่น เสื้อเชิ้ตหรือผ้าโพกหัว)", "พระศาสดา ﷺ ทำดุอานี้เมื่อสวมเสื้อผ้าใหม่ (ดุอาประจำวันสำหรับการแต่งกายอยู่ภายใต้ 'การแต่งตัว')"),
        "dua_rabbana_atina" to DuaText("ดีทั้งในโลกนี้และโลกหน้า", "พระเจ้าของเรา โปรดประทานความดีแก่เราในโลกนี้และความดีในปรโลก และโปรดปกป้องเราให้พ้นจากการลงโทษแห่งไฟนรก", "ดุอาของท่านศาสดา ﷺ ทำบ่อยที่สุด", "ดุอาที่รวบรวมความดีทุกอย่างของโลกนี้และปรโลก"),
        "dua_rabbi_zidni_ilma" to DuaText("เพิ่มพูนความรู้", "ข้าแต่พระเจ้าของข้าพระองค์ โปรดเพิ่มพูนความรู้แก่ข้าพระองค์ด้วย", "เพื่อเป็นการเพิ่มพูนความรู้", "อัลลอฮฺทรงบัญชาท่านศาสดาหมายเลข ﷺ ให้ขอเพิ่มพูนแต่ความรู้"),
        "dua_musa_sharh_sadr" to DuaText("การเปิดหีบ (Musa AS)", "ข้าแต่พระเจ้าของข้าพระองค์ โปรดขยายอกของข้าพระองค์ให้กว้างขวางขึ้น ทรงแบ่งเบางานของข้าพระองค์ และทรงปลดปมออกจากลิ้นของข้าพระองค์ เพื่อที่พวกเขาจะได้เข้าใจคำพูดของข้าพระองค์", "ก่อนสอบ กล่าวสุนทรพจน์ หรืองานยากๆ", "ดุอาของศาสดามูซา (AS) — จิตใจที่สงบและผ่อนคลายในการทำงาน"),
        "dua_la_tuzigh" to DuaText("ความแน่วแน่ของหัวใจ", "ข้าแต่พระเจ้าของเรา โปรดอย่าให้จิตใจของเราเบี่ยงเบนไปหลังจากที่พระองค์ได้ทรงชี้นำพวกเราแล้ว และโปรดประทานความเมตตาจากพระองค์แก่พวกเราด้วย แท้จริงพระองค์คือผู้ทรงประทาน", "เพื่อความแน่วแน่ในการชี้นำ", "ดุอาอ์เพื่อคงไว้ซึ่งความศรัทธา"),
        "dua_ya_muqallib" to DuaText("โอ้ เทิร์นเนอร์แห่งหัวใจ", "ข้าแต่ผู้พลิกดวงใจ โปรดรักษาใจของข้าพเจ้าให้มั่นคงต่อศาสนาของพระองค์", "พระศาสดา ﷺ มักทำดุอานี้", "ตามรายงานของอุมม์ ซาลามะห์ (RA) ดุอาของท่านศาสดาหมายเลข ﷺ ทำบ่อยที่สุด"),
        "dua_la_tuakhidhna" to DuaText("โองการสุดท้ายของ Surah Al-Baqarah", "พระเจ้าของเรา โปรดอย่าเอาพวกเราไปทำงานหากเราลืมหรือทำผิดพลาด ข้าแต่พระเจ้าของเรา โปรดอย่าทรงวางภาระแก่เราเหมือนกับที่พระองค์ทรงวางไว้ก่อนหน้าเรา ข้าแต่พระเจ้าของเรา โปรดอย่าสร้างภาระแก่เราด้วยสิ่งที่เราทนไม่ได้ ยกโทษให้เรา ยกโทษให้เรา และเมตตาเราด้วย คุณคือผู้พิทักษ์ของเรา ดังนั้นโปรดช่วยเราต่อสู้กับกลุ่มผู้ปฏิเสธศรัทธาด้วย", "ในเวลากลางคืนก่อนนอน — สองอายะฮ์สุดท้ายของซูเราะห์ อัล-บะกอเราะห์", "ใครก็ตามที่อ่านสองอายะฮ์สุดท้ายของ Surah al-Baqarah ในเวลากลางคืน พวกเขาจะเพียงพอแล้ว"),
        "dua_visiting_sick" to DuaText("เยี่ยมผู้ป่วย", "ฉันขอให้อัลลอฮ์ผู้ทรงอำนาจพระเจ้าแห่งบัลลังก์อันยิ่งใหญ่ทรงรักษาคุณ", "เจ็ดครั้งเมื่อไปเยี่ยมคนป่วย", "หากยังไม่ถึงเวลาแห่งความตาย อัลลอฮ์จะทรงรักษาเขาให้หายขาด"),
        "dua_ruqyah_pain" to DuaText("สำหรับความเจ็บปวดทางร่างกาย", "ฉันขอความคุ้มครองต่ออัลลอฮ์และอำนาจของพระองค์จากความชั่วร้ายของสิ่งที่ฉันรู้สึกและสิ่งที่ฉันกลัว", "วางมือของคุณตรงที่เจ็บ กล่าวบิสมิลลาห์สามครั้ง จากนั้นดุอาอ์นี้เจ็ดครั้ง", "ศาสดา ﷺ สอนเรื่องนี้กับ Uthman ibn Abil-'As (RA) เกี่ยวกับความเจ็บปวด"),
        "dua_ruqyah_nabawi" to DuaText("คำทำนาย Ruqyah สำหรับคนป่วย", "โอ้อัลลอฮ์ พระเจ้าแห่งมนุษยชาติ! ขจัดอันตรายและให้การรักษา เพราะพระองค์คือผู้ทรงรักษา ไม่มีวิธีรักษาใดนอกจากการรักษาของคุณ — การรักษาที่ไม่ทิ้งความเจ็บป่วยไว้เบื้องหลัง", "ขณะยื่นมือให้คนป่วย", "ศาสดาพยากรณ์ ﷺ ท่องสิ่งนี้เมื่อไปเยี่ยมสมาชิกที่ป่วยในครอบครัวของเขา"),
        "dua_kalimat_tammat" to DuaText("แสวงหาที่หลบภัยด้วยคำพูดที่สมบูรณ์แบบ", "ฉันขอความคุ้มครองด้วยพระวจนะอันสมบูรณ์แบบของอัลลอฮ์จากความชั่วร้ายของสิ่งที่พระองค์ทรงสร้าง", "เมื่อหยุด ณ สถานที่ใดสถานที่หนึ่งหรือในตอนเย็น", "ผู้ใดหยุด ณ ที่แห่งใดแห่งหนึ่งแล้วกล่าวคำนี้ ไม่มีอะไรจะทำร้ายเขาได้จนกว่าเขาจะจากไป"),
        "dua_evil_eye" to DuaText("คุ้มครองเด็ก (ตาปีศาจ)", "ฉันขอความคุ้มครองแก่คุณด้วยพระวจนะอันสมบูรณ์แบบของอัลลอฮ์จากทุกมารร้ายและสัตว์มีพิษทุกชนิด และจากดวงตาที่เป็นอันตรายทุกดวง", "พระศาสดา ﷺ ท่องสิ่งนี้กับฮะซันและฮุเซน (RA)", "ซุนนะฮฺ dua เพื่อปกป้องเด็กจากสายตาที่ชั่วร้ายและอันตราย (สำหรับเด็กคนหนึ่งพูดว่า 'U'īdhuka')"),
        "dua_seeing_afflicted" to DuaText("เห็นใครบางคนในการพิจารณาคดี", "การสรรเสริญทั้งมวลเป็นของอัลลอฮ์ ผู้ทรงช่วยเหลือฉันจากสิ่งที่พระองค์ทรงทดสอบพวกท่าน และทรงโปรดปรานฉันเหนือสิ่งสร้างของพระองค์มากมาย", "เมื่อเจอคนถูกพิจารณาคดี (พูดกับตัวเองเบาๆ)", "ผู้ที่กล่าวว่าจะปลอดภัยจากการทดลองนั้น"),
        "dua_istikhara" to DuaText("ละหมาดอัลอิสติฆอรา", "โอ้อัลลอฮฺ ฉันแสวงหาความดีด้วยความรู้ของพระองค์ ฉันแสวงหาความสามารถด้วยอำนาจของพระองค์ และฉันขอความโปรดปรานอันยิ่งใหญ่จากพระองค์ คุณมีอำนาจและฉันไม่มีเลย พระองค์ทรงรู้และฉันไม่รู้ และพระองค์คือผู้ทรงรอบรู้สิ่งเร้นลับ โอ้อัลลอฮ์ หากด้วยความรู้ของพระองค์ สิ่งนี้ (จงนำมาไว้ในจิตใจ) เป็นผลดีต่อศาสนาของฉัน ชีวิตของฉัน และบั้นปลายของฉัน ดังนั้นจงตัดสินให้ฉัน ทำให้มันง่ายสำหรับฉัน และโปรดอวยพรฉันด้วย และหากด้วยความรู้ของพระองค์ สิ่งนี้เป็นสิ่งที่ไม่ดีต่อศาสนาของฉัน และชีวิตของฉัน และบั้นปลายของฉัน ดังนั้นจงผินหลังให้มันไปจากฉัน และให้ฉันละทิ้งมัน และจงตัดสินให้ฉันในสิ่งที่ดี ไม่ว่ามันจะเป็นอย่างไรก็ตาม ก็ขอให้ฉันพอใจด้วยเถิด", "หลังจากการละหมาดด้วยความสมัครใจสองครั้ง เพื่อค้นหาสิ่งที่ดีที่สุดในเรื่องที่อนุญาต", "ศาสดา ﷺ สอนสหาย istikhara ในทุกเรื่องในขณะที่เขาสอนพวกเขาถึงอัลกุรอาน"),
    )
}
